class NomSituacionLaboral extends BaseNomSituacionLaboral {

    /**
     * Obtener un listado de los datos de los situaciones laborales.
     * 
     * @param int       $inicio Inicio de la busqueda.
     * @param int       $limite Limite maximo de la busqueda.
	 *
     * @return array    Listado de los datos de las situaciones laborales.
     */
    public static function obtenerListadoSituaciones($inicio = 0, $limite = 1000) {

        //Devolviendo el listado de situaciones laborales en forma de arreglo.
        $query = new Doctrine_Query ();
        $result = (($inicio != null) and ($limite != null))?
        $query->from('NomSituacionLaboral')
            ->orderBy('denominacion')
            ->limit($limite)
            ->offset($inicio)
            ->fetchArray():
            $query->from('NomSituacionLaboral')
            ->orderBy('denominacion')
            ->limit($limite)
            ->offset($inicio)
            ->fetchArray();
        return $result;
    }

    /**
     * Obtener un listado de los datos de los situaciones laborales(idsituacionlaboral, denominacion).
     *     
     * @return array    Listado de los datos de las situaciones laborales.
     */
    public static function obtenerListadoSituacionesCB() {

        //Devolviendo el listado de situaciones laborales en forma de arreglo.
        return Doctrine_Query::create()->select('idsituacionlaboral, denominacion, descripcion')
                        ->from('NomSituacionLaboral')
						->orderBy('denominacion')
                        ->fetchArray();
    }

    /**
     * Obtener la cantidad total de situaciones laborales.
     * 
     * @return int      Cantidad total de situaciones laborales.
     */
    public static function obtenerCantidadTotalSituaciones() {

        //Devolviendo la cantidad total de situaciones laborales.
        return Doctrine_Query::create()->select('COUNT(idsituacionlaboral) AS cantidad')
                        ->from('NomSituacionLaboral')
                        ->fetchOne()->cantidad;
    }

    /**
     * Obtener la situacion laboral dado el identificador.
     * 
     * @param $idsituacion             	Identificador de la situacion laboral
     * @return NomSituacionLaboral    	Objeto situacion laboral (clase del dominio).
     */
    public static function obtenerObjSituacionDadoId($idsituacion) {
        return Doctrine::getTable('NomSituacionLaboral')->find($idsituacion);
    }
    
	/**
     * Obtener si existe una situaci�n laboral a partir de la denominaci�n y la abreviatura.
     * 
	 * @param int $idsit    		Identificador de la situaci�n laboral.
	 * @param string $abrev    	 	Abreviatura de la situaci�n laboral.
     * @param string $denom    	 	Denominaci�n de la situaci�n laboral.
	 *
     * @return boolean    			Si existe la situaci�n laboral.
     */
    public static function existeSituacionLaboral($idsit, $abrev, $denom) {
		
		$query = Doctrine_Query::create()->select('COUNT(idsituacionlaboral) AS cantidad')
                        ->from('NomSituacionLaboral');
		if($abrev){
			$query->addWhere("abreviatura ilike ?", $abrev);
		}
		if($denom){
			$query->addWhere("denominacion ilike ?", $denom);
		}				
		if($idsit){
			$query->addWhere('idsituacionlaboral <> ?', $idsit);
		}		
		
		return    $query->fetchOne()->cantidad;
     }

    public static function obtenerDenomSituacionesLaborales() {

        //Devolviendo el listado de situaciones laborales en forma de arreglo.
        return Doctrine_Query::create()->select('idsituacionlaboral,denominacion')
            ->from('NomSituacionLaboral')
            ->orderBy('denominacion')
            ->fetchArray();
    }
	
	
	
	
	
	
	
	
	
	
/***************************VER DESDE AQUI***************************************************************/	
    public static function existeDenominacionSituacion($denominacion) {
        //Devolviendo la cantidad total de los salarios especificos.
        $query = new Doctrine_Query ();
        $result = $query->from('NomSituacionLaboral p')
                ->where("p.denominacion=?", array($denominacion))
                ->setHydrationMode(Doctrine::HYDRATE_ARRAY)
                ->execute();
          if(count($result)){
		   return 1;	
	         }else{
		   return 0;
		 }
     }
     
     public static function existeAbreviaturaSituacion($abreviatura) {
        //Devolviendo la cantidad total de los salarios especificos.
        $query = new Doctrine_Query ();
        $result = $query->from('NomSituacionLaboral p')
                ->where("p.abreviatura=?", array($abreviatura))
                ->setHydrationMode(Doctrine::HYDRATE_ARRAY)
                ->execute();
          if(count($result)){
		   return 1;	
	         }else{
		   return 0;
		 }
     }

    /**
     * Funcion para verificar si existe el color
     * @param $denom
     * @param $idtiporeunion
     */
    public function findByIdOrDenom($denom, $idsituacionlaboral = null)
    {
        try {
            $query = Doctrine_Query::create();
            $query->from('NomSituacionLaboral')
                ->where('fechainicio <= now() and (fechafin is null or fechafin > now())')
                ->andWhere("denominacion ilike '$denom'");
            if (!empty($idsituacionlaboral)) {
                $query->andWhere("idsituacionlaboral <> ?", $idsituacionlaboral);
            }
            $result = $query->count();
            if ($result > 0) {
                return true;
            } else {
                return false;
            }
        } catch (Doctrine_Exception $e) {
            throw $e;
        }
    }

}
